	}
	public int getUnknown4() {
		return unknown4;
	}
	public int getUnknown5() {
		return unknown5;
	}
	public int getFileID() {
		return fileID;
	}
	public DecmpfsHeader getDecmpfsHeader() {
		return _decmpfsHeader;
	}
	public long getRecordOffset() {
		return _offset;
	}

